#include "vehicle_panel_physics.hpp"
#include <btBulletDynamicsCommon.h>
#include <iostream>
#include <stdexcept>
using namespace ofo;void need(bool a,const char*s){if(!a)throw std::runtime_error(s);}
int main(){btDefaultCollisionConfiguration cfg;btCollisionDispatcher dispatch(&cfg);btDbvtBroadphase broad;btSequentialImpulseConstraintSolver solver;btDiscreteDynamicsWorld world(&dispatch,&broad,&solver,&cfg);world.setGravity({0,-9.81f,0});btBoxShape box({1,1,2});btRigidBody::btRigidBodyConstructionInfo ci(0,nullptr,&box);btRigidBody car(ci);car.setWorldTransform(btTransform(btQuaternion::getIdentity(),{0,5,0}));world.addRigidBody(&car,2,1|16);VehiclePanelDefinition d;d.name="bumper";d.mass=10;d.lo={-1,-.1f,1.8f};d.hi={1,.1f,2.2f};d.center=(d.lo+d.hi)*.5f;d.break_impulse=20;d.unlock_impulse=10;VehiclePanelPhysics panels(world,car,{}, {d});need(panels.snapshot()->empty(),"intact panels are implicit chassis parts");VehicleDamageContact hit;hit.position=d.center;hit.impulse=30000;hit.closing_speed=40;hit.radius=1;panels.update({hit},.01f);need(panels.detached()==1,"strong localized impact detaches panel");auto start=panels.snapshot()->at(0);need(start.detached,"published detached pose");world.removeRigidBody(&car);for(int i=0;i<50;i++){world.stepSimulation(.01f,0);panels.update({},.01f);}need(panels.snapshot()->at(0).transform[13]<start.transform[13]-.5f,"detached panel follows gravity");panels.clear();need(panels.snapshot()->empty()&&panels.detached()==0,"recover removes debris and resets attachments");std::cout<<"panel detachment, rigid motion and reset passed\n";}
